:root{--bs-body-bg:#f8f9fa;--bs-dark:#212529;--bs-light:#f8f9fa;--bs-info:#0dcaf0;--bs-secondary:#6c757d}
*{box-sizing:border-box}body{margin:0;font-family:system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;background:var(--bs-body-bg);color:#212529}
.container-fluid{width:100%;padding:0 12px}.row{display:flex;flex-wrap:wrap}.col-12{width:100%}
@media(min-width:768px){.col-md-3{width:25%}.col-md-9{width:75%}}
@media(min-width:992px){.col-lg-2{width:16.6667%}.col-lg-10{width:83.3333%}}
.min-vh-100{min-height:100vh}.bg-body-tertiary{background:#f8f9fa}.bg-dark{background:#212529}.text-light{color:#f8f9fa}.text-dark{color:#212529}.text-light-emphasis{color:#ced4da}.text-info-emphasis{color:#9eeaf9}
.p-0{padding:0}.p-2{padding:.5rem}.p-3{padding:1rem}.p-4{padding:1.5rem}.m-3{margin:1rem}.px-4{padding-left:1.5rem;padding-right:1.5rem}.py-4{padding-top:1.5rem;padding-bottom:1.5rem}.gap-2{gap:.5rem}
.border-bottom{border-bottom:1px solid}.border-secondary{border-color:var(--bs-secondary)}.h3{font-size:1.75rem}.small{font-size:.875rem}.mb-0{margin-bottom:0}.mb-2{margin-bottom:.5rem}
.nav{list-style:none;margin:0}.flex-column{display:flex;flex-direction:column}.nav-item{display:block}.w-100{width:100%}.text-start{text-align:left}
.btn{display:inline-block;padding:.5rem .75rem;border-radius:.375rem;border:1px solid transparent;background:transparent;cursor:pointer}.btn-outline-light{border-color:#f8f9fa;color:#f8f9fa}.btn-info{background:#0dcaf0;border-color:#0dcaf0}
.card{background:#fff;border:1px solid #dee2e6;border-radius:.5rem}.card-body{padding:1rem}.card-title{margin-top:0}.card-text{margin-bottom:0}.shadow-sm{box-shadow:0 .125rem .25rem rgba(0,0,0,.075)}
.d-none{display:none!important}.visually-hidden-focusable{position:absolute;left:-9999px}.visually-hidden-focusable:focus{left:0;z-index:1000}.position-absolute{position:absolute}.top-0{top:0}.start-0{left:0}.rounded-2{border-radius:.375rem}
@media(min-width:992px){.p-lg-5{padding:3rem}}